/* AI prompt library (2026-11-08). Shown under the main prompt on /QuizAiPrompt/Index with a copy button.
   Adds 4 handoff prompts. Safe to run more than once: rows with the same Code are overwritten with this text.
   The text is stored as hex so this file has no Korean letters and no BOM.
   Expected result: 4 rows (cb-handoff-out, cb-handoff-in, yyb-handoff-out, yyb-handoff-in) */
SET NOCOUNT ON;
SET XACT_ABORT ON;

IF OBJECT_ID(N'dbo.AiPromptLibrary', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.AiPromptLibrary
    (
        Id         int IDENTITY(1,1) NOT NULL CONSTRAINT PK_AiPromptLibrary PRIMARY KEY,
        Code       varchar(40)       NOT NULL CONSTRAINT UX_AiPromptLibrary_Code UNIQUE,
        Title      nvarchar(200)     NOT NULL,
        PromptText nvarchar(max)     NOT NULL,
        SortNo     int               NOT NULL CONSTRAINT DF_AiPromptLibrary_SortNo DEFAULT (0),
        UpdatedAt  datetime2(0)      NOT NULL
    );
END

BEGIN TRAN;
MERGE dbo.AiPromptLibrary AS t
USING (SELECT 'cb-handoff-out' AS Code, CAST(0x50AD00B33A00200018B130AE30AE2000142020004300680061006C006C0065006E00670065004200690062006C006500 AS nvarchar(200)) AS Title, CAST( AS nvarchar(max)) AS PromptText, 10 AS SortNo) AS s
ON t.Code = s.Code
WHEN MATCHED THEN UPDATE SET Title = s.Title, PromptText = s.PromptText, SortNo = s.SortNo, UpdatedAt = DATEADD(HOUR, 9, SYSUTCDATETIME())
WHEN NOT MATCHED THEN INSERT (Code, Title, PromptText, SortNo, UpdatedAt) VALUES (s.Code, s.Title, s.PromptText, s.SortNo, DATEADD(HOUR, 9, SYSUTCDATETIME()));

MERGE dbo.AiPromptLibrary AS t
USING (SELECT 'cb-handoff-in' AS Code, CAST(0x50AD00B33A00200074C7B4C51BBC30AE2000142020004300680061006C006C0065006E00670065004200690062006C006500 AS nvarchar(200)) AS Title, CAST( AS nvarchar(max)) AS PromptText, 20 AS SortNo) AS s
ON t.Code = s.Code
WHEN MATCHED THEN UPDATE SET Title = s.Title, PromptText = s.PromptText, SortNo = s.SortNo, UpdatedAt = DATEADD(HOUR, 9, SYSUTCDATETIME())
WHEN NOT MATCHED THEN INSERT (Code, Title, PromptText, SortNo, UpdatedAt) VALUES (s.Code, s.Title, s.PromptText, s.SortNo, DATEADD(HOUR, 9, SYSUTCDATETIME()));

MERGE dbo.AiPromptLibrary AS t
USING (SELECT 'yyb-handoff-out' AS Code, CAST(0x50AD00B33A00200018B130AE30AE20001420200059007500590075006E0042007500 AS nvarchar(200)) AS Title, CAST( AS nvarchar(max)) AS PromptText, 30 AS SortNo) AS s
ON t.Code = s.Code
WHEN MATCHED THEN UPDATE SET Title = s.Title, PromptText = s.PromptText, SortNo = s.SortNo, UpdatedAt = DATEADD(HOUR, 9, SYSUTCDATETIME())
WHEN NOT MATCHED THEN INSERT (Code, Title, PromptText, SortNo, UpdatedAt) VALUES (s.Code, s.Title, s.PromptText, s.SortNo, DATEADD(HOUR, 9, SYSUTCDATETIME()));

MERGE dbo.AiPromptLibrary AS t
USING (SELECT 'yyb-handoff-in' AS Code, CAST(0x50AD00B33A00200074C7B4C51BBC30AE20001420200059007500590075006E0042007500 AS nvarchar(200)) AS Title, CAST( AS nvarchar(max)) AS PromptText, 40 AS SortNo) AS s
ON t.Code = s.Code
WHEN MATCHED THEN UPDATE SET Title = s.Title, PromptText = s.PromptText, SortNo = s.SortNo, UpdatedAt = DATEADD(HOUR, 9, SYSUTCDATETIME())
WHEN NOT MATCHED THEN INSERT (Code, Title, PromptText, SortNo, UpdatedAt) VALUES (s.Code, s.Title, s.PromptText, s.SortNo, DATEADD(HOUR, 9, SYSUTCDATETIME()));

COMMIT;

SELECT Id, Code, LEN(PromptText) AS PromptLength, SortNo, UpdatedAt FROM dbo.AiPromptLibrary ORDER BY SortNo, Id;
